return {[1001]={desc="回合结束时，造成3%生命的毒系伤害。（毒系精灵免疫此效果）",note="中毒"},[1002]={desc="回合结束时，造成2%生命的火系伤害，并衰减一半层数。（火系精灵免疫此效果）",note="灼烧"},[1003]={desc="精灵离场，并选择队伍里一只其他精灵替换入场。本回合入场的精灵免疫此效果。",note="脱离"},[1004]={desc="冻结5%生命，若当前生命低于冻结比例，则力竭。（冰系精灵免疫此效果）",note="冻结"},[1005]={desc="通过主动更换精灵的方式入场时，使用第一个能量满足要求，并带有迅捷的技能。",note="迅捷"},[1006]={desc="退化到上一阶，种族资质相应降低。（可退化的精灵才可以获得萌化，下场不会消失）",note="萌化"},[1007]={desc="该技能需要先蓄力1回合，下回合才能释放。蓄力期间免疫所有离场效果。",note="蓄力"},[1008]={desc="回合结束时，从寄生来源吸收2%生命。（草系精灵免疫此效果）",note="寄生"},[1009]={desc="使己方队伍中所有的「啃咬」和「虫群」技能获得奉献对应的强化效果。",note="奉献"},[1010]={desc="入场后的首次行动，会获得额外效果。",note="迸发"},[1011]={desc="使敌方本次无法释放对应技能。",note="打断"},[1012]={desc="增加属性、技能威力、连击数，以及降低能耗、吸血、过载等效果。（不包括类型为“印记”、“特性”、“其他”的效果）",note="增益"},[1013]={desc="降低属性、技能威力、连击数，以及增加能耗、中毒、灼烧、寄生、冻结、萌化、引电等效果。（不包括类型为“印记”、“特性”、“其他”的效果）",note="减益"},[1014]={desc="印记效果，回合结束造成3%生命的毒系伤害。",note="中毒印记"},[1015]={desc="若敌方使用状态技能，则本技能应对成功，本次行动必定先手，且触发应对效果。",note="应对状态"},[1016]={desc="若敌方使用攻击技能，则本技能应对成功，本次行动必定先手，且触发应对效果。使用后，携带的防御技能进入1回合冷却。",note="应对攻击"},[1017]={desc="若敌方使用防御技能，则本技能应对成功，本次行动必定先手，且触发应对效果。",note="应对防御"},[1018]={desc="印记效果，全技能威力+10%。",note="攻击印记"},[1019]={desc="印记效果，场上的精灵离场后，更换入场的精灵失去6%生命。",note="棘刺印记"},[1020]={desc="技能行动的优先级，先手度更高的技能忽略双方精灵速度差异，优先释放，先手度可叠加。",note="先手"},[1021]={desc="印记效果，回合结束时获得1能量。",note="光合印记"},[1022]={desc="印记效果，全技能能耗-1。",note="湿润印记"},[1023]={desc="印记效果，攻击技能获得迸发：本次威力+10。",note="蓄电印记"},[1024]={desc="精灵离场，并立即入场。本回合入场的精灵免疫此效果。",note="返场"},[1026]={desc="精灵离场，并随机选择队伍里一只其他精灵替换入场。本回合入场的精灵免疫此效果。",note="紧急脱离"},[1027]={desc="印记效果，先手攻击时，本次技能威力+20%。",note="风起印记"},[1028]={desc="印记效果，场上的精灵离场后，更换入场的精灵失去1能量。",note="降灵印记"},[1029]={desc="造成伤害时，根据吸血比例和造成伤害值，回复生命。",note="吸血"},[1030]={desc="印记效果，全攻击技能威力+30%，且能耗+1。",note="蓄势印记"},[1031]={desc="印记效果，释放3能耗技能后，获得双攻+40%。",note="龙噬印记"},[1032]={desc="印记效果，速度-10。",note="减速印记"},[1033]={desc="回合开始时，带有“传动X”的技能会向下移动X个位置，该效果可叠加。",note="传动"},[1035]={desc="印记效果，使用非幻系技能攻击拥有此印记的精灵时，会触发星陨印记，消耗全部星陨层数，对其造成额外的幻系伤害。",note="星陨印记"},[1036]={desc="包括中毒和中毒印记。",note="中毒效果"},[3005]={desc="改变连击次数，仅对有连击的技能生效。",note="连击数"},[3006]={desc="天气为沙暴时，双方的地系技能能耗减半。",note="沙暴"},[3007]={desc="天气为暴风雪时，双方每回合结束获得2层冻结。（冰系精灵免疫此效果）",note="暴风雪"},[3008]={desc="天气为雨天时，双方的水系技能威力+75%。",note="雨天"},[3009]={desc="通过主动更换精灵或触发脱离效果的方式下场。（不包括精灵力竭后下场）",note="离场"},[3010]={desc="精灵下场后印记不会消失，新入场的精灵会继承印记效果。精灵最多同时拥有1种正面印记和1种负面印记。",note="印记"},[3011]={desc="使用后会变为指定范围内的随机技能，且能耗-1。使用该随机技能后会变回原技能。",note="巧变"},[3012]={desc="获得增益时，会额外获得1层。",note="萌芽印记"},[3013]={desc="使用附加中毒X的技能会使敌方获得X层中毒。",note="附加中毒"},[3014]={desc="增益的其中一种类型，指提升物攻、魔攻、物防、魔防、速度的增益。",note="属性增益"},[3015]={desc="非本系血脉的精灵，包括非本系的系别血脉、首领血脉、奇异血脉、污染血脉等。",note="混血精灵"},[3018]={desc="减益的其中一种类型，指降低物攻、魔攻、物防、魔防、速度的减益。",note="属性减益"},[3019]={desc="可以从2个效果中选择1个使用。（2个效果视为相同技能，分别记为「明」和「暗」）",note="选择"},[3020]={desc="印记效果，场上的精灵离场后，更换入场的精灵获得随机5层属性减益。",note="暗涌印记"},[3021]={desc="天气为雷鸣时，双方每回合结束获得1层引电。（电系精灵免疫此效果）",note="雷鸣"},[3022]={desc="获得2层引电时，立即受到25%生命的电系伤害，并失去2层引电。（电系精灵免疫此效果）",note="引电"},[3023]={desc="处于禁足状态时，精灵无法离场，且无法获得新的禁足状态。",note="禁足"},[3024]={desc="该状态下会隐藏精灵的信息，自己行动或被敌方攻击时解除。",note="木桶状态"},[3025]={desc="该状态下会隐藏精灵的信息，自己行动或被敌方攻击时解除。",note="月陨星状态"},[3026]={desc="光系技能，1能耗，对敌方造成60威力物伤。",note="透射"}}